 box.querySelector('.np-find input')?.addEventListener('input',e=>{q=e.target.value.trim().toLowerCase();paint()});
 box.onclick=e=>{const b=e.target.closest('[data-np]');if(!b)return;const v=b.dataset.np;on.has(v)?on.delete(v):on.add(v);b.classList.toggle('on',on.has(v));b.setAttribute('aria-pressed',on.has(v));count();box.dispatchEvent(new Event('np'))};
