const chLogo=(id,name)=>CH_DOMAINS[id]?logoImg(CH_DOMAINS[id],(name||id)[0].toUpperCase(),CH_COLORS[id]):CH_ICONS[id]?`<span class="logo" style="background:${CH_COLORS[id]||'var(--ink)'};color:#fff">${icon(CH_ICONS[id],18)}</span>`:logoImg(null,(name||id)[0].toUpperCase(),CH_COLORS[id]);
// plain card text where the engine's description is technical (setup details stay in the setup window)
const CH_PLAIN={slack:'Talk to your agents in Slack.',google_chat:'Talk to your agents in Google Chat.',a2a:'Let other AI agents send work to your agents.',buzz:'Talk to your agents in Buzz.',signal:'Talk to your agents in Signal.',email:'Talk to your agents by email.',teams:'Talk to your agents in Microsoft Teams chats.',line:'Talk to your agents in LINE.',simplex:'Talk to your agents in SimpleX Chat.',weixin:'Talk to your agents from a personal WeChat account.',wecom_callback:'Two-way chat with your agents in WeCom.',whatsapp_cloud:'Talk to your agents in WhatsApp through Meta’s own service.',relay:'Connect your agents to other chat apps through a relay.'};
const CH_COLORS={telegram:'#229ED9',discord:'#5865F2',whatsapp:'#25D366',slack:'#4A154B',email:'#0158cb',signal:'#3A76F0',sms:'#F22F46',matrix:'#0b0c10',mattermost:'#1E325C'};
PAGES.channels=async(p,el)=>{const gone=pageTok(el);
 setActions('');
 const d=await H('/messaging/platforms');if(gone())return;const list=(d.platforms||[]).sort((a,b)=>(b.state==='connected')-(a.state==='connected')||(b.configured-a.configured));Pages.platforms=list;Pages._chEnv=d.env_path||null;
 // saved changes that wait for a restart stay announced here until the agents restart
 if(!list.some(c=>c.state==='pending_restart')&&S._chRestart&&Date.now()-(S._chRestartAt||0)>90000)S._chRestart=false;
 const waitN=list.filter(c=>c.state==='pending_restart').length;
 el.innerHTML=`${(waitN||S._chRestart)&&S.me?.admin!==false?`<div class="panel card ch-restart" role="status">${icon('alert',18)}<div class="txt"><b>Saved changes are waiting for a restart</b><span>${waitN?esc(list.filter(c=>c.state==='pending_restart').map(c=>c.name).join(', '))+(waitN===1?' connects':' connect'):'Your changes apply'} after the agents restart (about 20 seconds; replies in progress finish first).</span></div><button class="primary" data-act="ch-restart-now">${icon('refresh',15)}Restart now</button></div>`:''}<div class="grid-cards">${list.map((c,i)=>`<button class="card tile" ${st(i)} data-act="ch-open" data-id="${esc(c.id)}"><div class="tile-top">${chLogo(c.id,c.name)}<div><h3>${esc(c.name)}</h3></div></div><p>${esc(CH_PLAIN[c.id]||c.description||'')}</p><div class="tile-foot">${c.configured||c.state==='connected'?chStateChip(c):'<span class="chip">Not set up</span>'}<span style="color:var(--muted)">${icon('chevR',16)}</span></div></button>`).join('')}</div>`;
};
ACT['gw-restart']=()=>restartGateway();
const chNeedRestart=()=>{S._chRestart=true;S._chRestartAt=Date.now()};
ACT['ch-restart-now']=async a=>{a.disabled=true;await restartGateway();S._chRestart=false;const b=a.closest('.ch-restart');if(b)leave(b,210);laterReload(26000)};
ACT['ch-open']=a=>channelDrawer(a.dataset.id);
function channelDrawer(id){const c=(Pages.platforms||[]).find(x=>x.id===id);if(!c)return;
 const guided=id==='telegram'||id==='whatsapp'?`<div class="panel card" style="box-shadow:none;padding:16px 18px;margin-bottom:8px"><b style="font-size:14px">Guided setup</b><p class="hint" style="margin-top:4px">${id==='telegram'?'aqeelOS walks you through creating a bot with @BotFather and fills in the token.':'Pair WhatsApp by scanning a QR code with your phone.'}</p><button style="margin-top:10px" data-act="onboard" data-id="${id}">${icon('play',15)}Start guided setup</button><div id="onboard"></div></div>`:'';
 const shared=CH_SHARED.has(id),admin=S.me?.admin!==false;
 const d=drawer(c.name,`<div style="display:flex;align-items:center;gap:14px;margin-bottom:18px"><span class="logo-lg">${chLogo(id,c.name)}</span><div><b style="font-size:15px">${esc(c.name)}</b><div style="margin-top:4px">${c.configured||c.enabled||c.state==='connected'?chStateChip(c):'<span class="chip">Not set up</span>'}${c.updated_at?`<small class="ch-upd">updated ${when(c.updated_at)}</small>`:''}</div></div></div>${CH_PLAIN[id]&&c.description?`<p class="hint" style="margin:-6px 0 16px">${esc(c.description)}</p>`:''}${c.error_message?`<p class="err-line">${esc(c.error_message)}</p>`:''}
  ${shared&&c.configured?`<div class="ch-onrow"><div><b>Switched on</b><p class="hint" style="margin:2px 0 0">Off keeps its settings; no agent uses it until you switch it on again.</p></div>${toggle(c.enabled,'Switched on','id="chEnabled"')}</div>`:''}${guided}${(c.env_vars||[]).map(chField).join('')||'<p class="hint">This channel needs no settings.</p>'}
  ${c.ingress_url?`<h3 class="ch-h">Callback address</h3>${chCopy('Callback URL',c.ingress_url)}<p class="hint">Paste this into the app’s own settings so it can send messages to your agents.</p>`:''}
  ${shared&&c.configured?'':c.configured?`<input type="checkbox" id="chEnabled" hidden ${c.enabled?'checked':''}><p class="hint">To pause it, set <b>Owned by</b> to <b>Nobody</b> on Channels › Connections.</p>`:`<input type="checkbox" id="chEnabled" hidden checked>`}${c.docs_url?`<p class="hint"><a href="${esc(c.docs_url)}" target="_blank" rel="noopener">Setup guide</a></p>`:''}${admin&&Pages._chEnv?`<p class="hint ch-envp">These settings are saved in the agent’s settings file (.env). <a href="#" data-act="ch-envdir">Show it in Files</a></p>`:''}`,`<button data-act="ch-test" data-id="${esc(id)}">Test</button><button class="primary" id="chSave">Save</button>`);
 chWire(d);
 // API server and webhooks serve every agent, so they get a real on/off switch (it saves at once)
 d.querySelector('#chEnabled.switch')?.addEventListener('change',async e=>{const sw=e.target,on=sw.checked;sw.disabled=true;
  try{const r=await put(H,'/messaging/platforms/'+encodeURIComponent(id),{enabled:on});c.enabled=on;if(!r.hot_served)chNeedRestart();toast(c.name+(on?' on for every agent':' off for every agent')+(r.hot_served?' · works at once':' · applies after the agents restart'));reload();laterReload(4000)}catch(er){sw.checked=!on;fail(er)}finally{sw.disabled=false}});
 const save=d.querySelector('#chSave'),test=d.querySelector('[data-act="ch-test"]');
 save.onclick=async()=>{const {env,clear,bad}=chCollect(d,c.env_vars||[]);if(bad)return toast('Check the fields marked in red','err');
  if(c.configured&&!Object.keys(env).length&&!clear.length)return toast('Nothing to save. Change a setting first.','err');
  // a paused channel stays paused on Save unless the person says otherwise
  const resume=c.configured&&!c.enabled&&!shared&&admin?await confirmBox('Switch '+c.name+' on too?','It is paused now, so no agent answers it. Switch it on with these settings, or keep it paused.','Switch on',false):false;
  save.disabled=true;if(test)test.disabled=true;
  try{const r=await put(H,'/messaging/platforms/'+encodeURIComponent(id),{enabled:!!d.querySelector('#chEnabled')?.checked,env,...(clear.length?{clear_env:clear}:{})});
   if(resume)await post(UI,'/ui/channels/pause',{agent:agentProfile()||'default',platform:id,on:true}).catch(fail);
   closeLayers();if(!r.hot_served)chNeedRestart();toast(r.hot_served?c.name+' saved and connecting':c.name+' saved · restart the agents to connect');reload();laterReload(4000)}catch(e){fail(e)}finally{save.disabled=false;if(test)test.disabled=false}};
}
// channel settings: plain hints, allowlists as rows you add and remove, format checks before saving
const CH_SHARED=new Set(['api_server','webhook']);
const CH_HINT={WHATSAPP_ALLOWED_USERS:'Phone numbers allowed to talk to the agent: country code + number, digits only (e.g. 6281234567890). Leave empty to approve people one by one under Channels › Who can message.',TELEGRAM_ALLOWED_USERS:'Telegram user IDs (numbers like 123456789). To find someone’s ID, they message @userinfobot on Telegram. Leave empty to approve people under Channels › Who can message.',SLACK_ALLOWED_USERS:'Slack member IDs (like U012AB3CD). In Slack: click a person › ⋯ › Copy member ID. Leave empty to approve people under Channels › Who can message.',DISCORD_ALLOWED_USERS:'Discord user IDs (long numbers). In Discord: turn on Developer Mode, then right-click a person › Copy User ID.',SIGNAL_ALLOWED_USERS:'Phone numbers with country code (like +6281234567890).',WHATSAPP_DM_POLICY:'pairing = new people ask first and you approve them; allowlist = only the numbers above; open = anyone.'};
const CH_LINK={TELEGRAM_ALLOWED_USERS:['https://t.me/userinfobot','Find my user ID']};
const chIsBool=v=>/\(true\/false\)|_ENABLED$/i.test((v.prompt||'')+' '+v.key);
const chIsList=v=>v.is_list===true||(v.is_list==null&&!v.is_password&&/_ALLOWED_USERS$/.test(v.key));
const chSplit=s=>[...new Set(String(s||'').split(/[\s,;]+/).map(x=>x.trim()).filter(Boolean))];
const chAllowChip=x=>`<span class="allow-chip"><span>${esc(x)}</span><button type="button" class="ghost icon" data-allow-rm aria-label="Remove ${esc(x)}">${icon('x',13)}</button></span>`;
const chCopy=(label,v)=>`<div class="wac-copy"><span>${esc(label)}</span><code>${esc(v)}</code><button class="ghost icon" data-act="copy-text" data-text="${esc(v)}" aria-label="Copy ${esc(label)}">${icon('copy',15)}</button></div>`;
function chField(v){Lang.keep(v.key);v=CH_HINT[v.key]?{...v,description:CH_HINT[v.key]}:v;const req=v.required?' *':'',lab=esc((v.prompt||v.key).replace(/\s*\(true\/false\)/i,'')),k=esc(v.key);
 const hint=`<p class="hint">${esc(v.description||'')}${v.url?` <a href="${esc(v.url)}" target="_blank" rel="noopener">Get it</a>`:''}${CH_LINK[v.key]?` <a href="${CH_LINK[v.key][0]}" target="_blank" rel="noopener">${CH_LINK[v.key][1]}</a>`:''}</p>${v.help&&v.help!==v.description?`<p class="hint">${esc(v.help)}</p>`:''}<p class="err-line ch-err" hidden></p>`;
 if(chIsBool(v))return `<div class="ch-f" data-cf="${k}"><label>${lab}${req}</label><select data-env="${k}"><option value="">${v.is_set?'Leave as it is':'Not set'}</option><option value="true">On</option><option value="false">Off</option></select>${hint}</div>`;
 if(chIsList(v)){const known=v.value!=null||!v.is_set,items=chSplit(v.value);return `<div class="ch-f" data-cf="${k}"><label>${lab}${req}</label><div class="allow" data-orig="${esc(items.join(','))}" data-known="${known?1:''}">${items.map(chAllowChip).join('')}<input class="allow-in" placeholder="${known?'Add one and press Enter':'Saved · add to replace the list'}" aria-label="Add to ${lab}" autocomplete="off"><button type="button" class="ghost small" data-allow-add>${icon('plus',14)}Add</button></div>${hint}</div>`}
 return `<div class="ch-f" data-cf="${k}"><label>${lab}${req}</label><input data-env="${k}" ${v.is_password||/TOKEN|SECRET|PASSWORD|KEY/.test(v.key)?'type="password" autocomplete="off"':''} placeholder="${v.is_set?esc(v.redacted_value||'Set · leave blank to keep'):esc(v.description||'')}">${hint}</div>`}
const chClearErr=el=>{const f=el.closest('.ch-f');const er=f?.querySelector('.ch-err');if(er)er.hidden=true;f?.classList.remove('bad')};
function chWire(d){d.querySelectorAll('.allow').forEach(box=>{const inp=box.querySelector('.allow-in');
 const add=()=>{const have=new Set([...box.querySelectorAll('.allow-chip:not(.closing)>span')].map(s=>s.textContent));for(const x of chSplit(inp.value))if(!have.has(x)){have.add(x);inp.insertAdjacentHTML('beforebegin',chAllowChip(x))}inp.value='';box.dataset.touched=1;chClearErr(box)};
 const rm=chip=>{if(!chip)return;leave(chip,150);box.dataset.touched=1;chClearErr(box)};
 inp.onkeydown=e=>{if(e.key==='Enter'||e.key===','){e.preventDefault();if(inp.value.trim())add()}else if(e.key==='Backspace'&&!inp.value){const last=[...box.querySelectorAll('.allow-chip:not(.closing)')].pop();rm(last)}};
 inp.onpaste=()=>setTimeout(()=>{if(chSplit(inp.value).length>1||/[,;]/.test(inp.value))add()},0);
 box.querySelector('[data-allow-add]').onclick=()=>{if(inp.value.trim())add();inp.focus()};
 box.addEventListener('click',e=>{const b=e.target.closest('[data-allow-rm]');if(b)rm(b.closest('.allow-chip'));else if(e.target===box)inp.focus()})});
 d.addEventListener('input',e=>{if(e.target.closest?.('.ch-f'))chClearErr(e.target)})}
// the engine's own format checks for Telegram and Slack
function chCheck(key,val,v){const t=String(val||'').trim();if(!t)return null;
 if(key==='TELEGRAM_BOT_TOKEN'&&!/^\d+:[A-Za-z0-9_-]{30,}$/.test(t))return 'Paste the whole token from @BotFather (like 123456789:ABC…).';
 if(key==='TELEGRAM_ALLOWED_USERS'){const b=chSplit(t).find(x=>!/^\d+$/.test(x));if(b)return b+' is not a Telegram user ID. Those are numbers only.'}
 const pre={SLACK_BOT_TOKEN:'xoxb-',SLACK_APP_TOKEN:'xapp-'}[key];if(pre&&!t.startsWith(pre))return (v?.prompt||key)+' starts with '+pre;
 if(key==='SLACK_ALLOWED_USERS'){const b=chSplit(t).find(x=>x!=='*'&&!/^[UW][A-Z0-9]{2,}$/.test(x));if(b)return b+' does not look like a Slack member ID. They look like U01ABC2DEF3.'}
 return null}
// what Save sends: filled fields, changed allowlists (an emptied one is cleared), and the first problem found
function chCollect(d,vars){const env={},clear=[];let bad=null;
 const mark=(f,m)=>{const er=f.querySelector('.ch-err');if(er){er.textContent=m;er.hidden=false}f.classList.add('bad');if(!bad){bad=f;f.querySelector('input,select')?.focus()}};
 for(const v of vars){const f=d.querySelector(`[data-cf="${CSS.escape(v.key)}"]`);if(!f)continue;const box=f.querySelector('.allow');let val;
  if(box){const items=[...box.querySelectorAll('.allow-chip:not(.closing)>span')].map(s=>s.textContent);for(const x of chSplit(box.querySelector('.allow-in').value))if(!items.includes(x))items.push(x);val=items.join(',');
   if(val===box.dataset.orig)val=null;else if(!val){if(v.is_set&&box.dataset.known&&box.dataset.touched)clear.push(v.key);val=null}}
  else val=f.querySelector('[data-env]')?.value.trim()||null;
  if(val!=null)env[v.key]=val;
  const m=chCheck(v.key,val,v);if(m)mark(f,m);else if(v.required&&!v.is_set&&!val)mark(f,'Fill this in.')}
 return {env,clear,bad}}
ACT['ch-envdir']=(a,e)=>{e?.preventDefault();const p=Pages._chEnv;if(!p)return;closeLayers();if(typeof fAgent==='function')S._fileAgent=fAgent();S.filePath=p.replace(/\/[^/]*$/,'')||'/';S._placesOk=null;go('/agents/files')};
ACT['ch-test']=async a=>{if(a.disabled)return;a.disabled=true;try{const r=await post(H,'/messaging/platforms/'+encodeURIComponent(a.dataset.id)+'/test');toast(r.ok||r.connected?'Live connection works':(r.message||r.detail||'Not connected yet'),r.ok||r.connected?undefined:'err')}catch(e){fail(e)}finally{a.disabled=false}};
ACT['onboard']=async a=>{const id=a.dataset.id;const box=$('#onboard');a.disabled=true;
 try{const start=id==='telegram'?await post(H,'/messaging/telegram/onboarding/start',{bot_name:'aqeelOS'}):await post(H,'/messaging/whatsapp/onboarding/start',{mode:'bot'});
  const pid=start.pairing_id||start.id;
  // already linked (its saved login exists): don't re-apply, which would reset settings and restart every agent's channels
  if(id==='whatsapp'&&/connected/.test(start.status||'')&&!start.qr_payload){del(H,'/messaging/whatsapp/onboarding/'+encodeURIComponent(pid)).catch(()=>{});box.innerHTML=`<p class="hint" style="margin-top:12px">${icon('check',15)} This WhatsApp is already linked${start.account_name?' ('+esc(start.account_name)+')':''}. Nothing to scan. To link a different phone, use <b>Link again</b>.</p>`;return}
  const show=s=>{const qr=s.qr_data_url||s.qr_png||s.qr_image||(s.qr_payload?'/ui/qr?d='+encodeURIComponent(s.qr_payload):null);const link=s.deep_link||s.bot_url||s.url||s.link;box.innerHTML=`<div style="margin-top:12px">${qr?`<img src="${esc(qr)}" alt="QR code" style="width:220px;height:220px;display:block;margin:0 auto 10px;border-radius:12px;background:#fff;padding:8px">${s.qr_payload&&id==='whatsapp'?'<ol class="qr-steps"><li>Open WhatsApp on the phone you want aqeelOS to use.</li><li>Tap <b>Settings</b> (iPhone) or <b>⋮</b> (Android), then <b>Linked devices</b>.</li><li>Tap <b>Link a device</b> and point the camera at this code.</li></ol>':''}`:''}${s.qr_text&&!qr?`<pre class="action-log" style="font-size:7px;line-height:1">${esc(s.qr_text)}</pre>`:''}${link?`<p><a href="${esc(link)}" target="_blank" rel="noopener">${esc(link)}</a></p>`:''}${s.instructions||s.message?`<p class="hint">${esc(s.instructions||s.message)}</p>`:''}<p class="hint">Status: ${esc(pretty(s.status||'waiting'))}</p><button class="ghost" data-act="onboard-cancel" data-id="${id}" data-pid="${esc(pid)}">Cancel setup</button></div>`};show(start);
  for(let i=0;i<300&&box.isConnected;i++){await sleep(2000);const s=await H(`/messaging/${id}/onboarding/${encodeURIComponent(pid)}`);show(s);
   if(/ready|complete|paired|connected|approved/.test(s.status||'')){const body=id==='telegram'?{allowed_user_ids:(s.user_ids||s.allowed_user_ids||(s.user_id?[String(s.user_id)]:[])).map(String)}:{mode:'bot'};await post(H,`/messaging/${id}/onboarding/${encodeURIComponent(pid)}/apply`,body);closeLayers();toast('Channel connected');reload();return}
   if(/fail|error|expired|cancel/.test(s.status||''))return}
 }catch(e){fail(e);a.disabled=false}};
ACT['onboard-cancel']=async a=>{try{await del(H,`/messaging/${a.dataset.id}/onboarding/${encodeURIComponent(a.dataset.pid)}`)}catch{}$('#onboard').innerHTML='';toast('Setup cancelled')};

/* ===================== Automations › Webhooks ===================== */
PAGES.webhooks=async(p,el)=>{const gone=pageTok(el);
 const d=await H('/webhooks');if(gone())return;
 setActions(d.enabled?`<button class="primary" data-act="wh-new">${icon('plus',16)}New webhook</button>`:'');
 const subs=d.subscriptions||[];
 const list=subs.length?`<h3 class="sd-h wh-count">${plural(subs.length,'webhook')}</h3><div class="card list ${d.enabled?'':'wh-off'}">${subs.map((w,i)=>{const url=location.origin+(w.url_path||'/webhooks/'+encodeURIComponent(w.name));return `<div class="row" ${st(i)}><div class="main-c"><span class="ic ${w.enabled!==false&&d.enabled?'blue':''}">${icon('hook',18)}</span><div class="txt"><b>${esc(w.name)}${w.deliver_only?` <span class="chip sm-chip" title="Sent on as it arrives, without the agent">Direct</span>`:''}</b>${w.description?`<span class="sched-desc">${esc(w.description)}</span>`:''}<span>${esc(url)} · ${esc((w.events||[]).join(', ')||'any event')} · ${esc(whDeliverName(w.deliver))}</span></div></div><div class="act"><button class="ghost icon" title="Copy URL" aria-label="Copy URL" data-act="copy-text" data-text="${esc(url)}">${icon('copy',16)}</button>${toggle(w.enabled!==false,'Enabled','data-act="wh-toggle" data-name="'+esc(w.name)+'"')}<button class="ghost icon" title="Delete" aria-label="Delete" data-act="wh-del" data-name="${esc(w.name)}">${icon('trash',16)}</button></div></div>`}).join('')}</div>`:'';
 const restart=Pages._whRestart?`<div class="tz-note ${Pages._whRestart.busy?'':'warn'} wh-restart">${icon(Pages._whRestart.busy?'refresh':'alert',15)}<span>${esc(Pages._whRestart.msg)}</span>${Pages._whRestart.busy?'':`<button type="button" data-act="wh-restart">Restart agents</button>`}</div>`:'';
 // switched off: the saved webhooks stay visible (greyed), so nothing seems lost
 if(!d.enabled){el.innerHTML=restart+emptyBox('Webhooks are off','Turn on the webhook channel so other services can send events to aqeelOS.',`<button class="primary" data-act="wh-enable">Turn on webhooks</button>`)+(subs.length?`<p class="hint" style="margin:18px 0 0">These are saved and start working again once webhooks are on.</p>${list}`:'');return}
 el.innerHTML=restart+(subs.length?list:emptyBox('No webhooks yet','Give a service like GitHub or Stripe a URL to call, and tell aqeelOS what to do with each event.',`<button class="primary" data-act="wh-new">${icon('plus',16)}New webhook</button>`))+`<p class="hint" style="margin-top:12px">Outside services post to the address shown on each webhook. Each one must sign its requests with the webhook secret. Changes work at once, without a restart. A webhook that is switched off turns away the events sent to it.</p>`;
};
// where a webhook's result goes: the engine's six choices, then the agent's own chats by name
const WH_DELIVER=[['log','Keep it in the log (no message)'],['github_comment','A comment on the GitHub pull request or issue'],['telegram','Telegram (home channel)'],['discord','Discord (home channel)'],['slack','Slack (home channel)'],['email','Email (home address)']];
const whDeliverName=v=>!v||v==='log'?'kept in the log':v==='github_comment'?'GitHub comment':(WH_DELIVER.find(x=>x[0]===v)||[])[1]?.replace(/ \((home channel|home address)\)$/,'')||(typeof deliverName==='function'?deliverName({deliver:v},SCHED?.info?.names):pretty(v));
const whDelOpts=tg=>WH_DELIVER.map(([v,l])=>`<option value="${v}" ${v==='log'?'selected':''}>${esc(l)}</option>`).join('')+tg.filter(t=>t.id!=='local'&&!WH_DELIVER.some(x=>x[0]===t.id)&&!/^bot-chat/.test(t.id)).map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');
// turning webhooks on restarts the agents: follow that restart and offer it again when it fails
async function whWatch(){Pages._whRestart={busy:true,msg:'Webhooks are on. Restarting the agents so they start receiving…'};reload();
 for(let i=0;i<20;i++){await sleep(1500);let s;try{s=await H('/actions/gateway-restart/status?lines=5')}catch{continue}if(s.running)continue;
  if(s.exit_code!=null&&s.exit_code!==0){Pages._whRestart={msg:'Webhooks are on, but the agents did not restart (code '+s.exit_code+'). Restart them to start receiving.'};toast('The agents did not restart','err')}
  else{Pages._whRestart=null;toast('Agents restarted · webhooks are receiving')}
  if(route().page?.id==='webhooks')reload();return}
 Pages._whRestart={msg:'Webhooks are on. The restart is taking long: if they don’t appear soon, restart the agents.'};if(route().page?.id==='webhooks')reload()}
ACT['wh-enable']=async()=>{let r;try{r=await post(H,'/webhooks/enable')}catch(e){return fail(e)}
 if(r?.restart_started)return whWatch();
 Pages._whRestart=r?.restart_error||r?.needs_restart?{msg:r.restart_error?'Webhooks are on, but the agents could not restart: '+r.restart_error:'Webhooks are on. Restart the agents so they start receiving.'}:null;
 toast(Pages._whRestart?'Webhooks on · restart needed':'Webhooks on',Pages._whRestart&&r.restart_error?'err':undefined);reload()};
ACT['wh-restart']=async()=>{Pages._whRestart=null;await restartGateway();reload()};
// data-agent: the webhook of that agent (All agents rows)
ACT['wh-toggle']=async a=>{const on=a.checked,ag=a.dataset.agent,n=a.dataset.name;a.disabled=true;try{await put(H,prof('/webhooks/'+encodeURIComponent(n)+'/enabled',ag),{enabled:on});toast(n+(on?' on for ':' off for ')+ident(ag||viewing()).name+' · works at once');reload()}catch(e){a.checked=!on;fail(e)}finally{a.disabled=false}};   // one change at a time, then the list as saved
ACT['wh-del']=async a=>{const ag=a.dataset.agent,n=a.dataset.name,who=ident(ag||viewing()).name;if(!await confirmBox('Delete '+n+'?',`Calls to “${n}” stop working, and ${who} no longer gets its events.`))return;try{await del(H,prof('/webhooks/'+encodeURIComponent(n),ag));toast(n+' removed from '+who);reload()}catch(e){fail(e)}};
ACT['wh-new']=async()=>{const tg=(await H('/cron/delivery-targets?profile='+encodeURIComponent((agentProfile()||'default'))).catch(()=>({targets:[]}))).targets||[];
 const d=drawer('New webhook',`<label>Name</label><input id="whName" maxlength="64" placeholder="github-review"><label>Description</label><input id="whDesc" placeholder="Review every push"><label>Events</label><input id="whEv" placeholder="push, pull_request (blank = any)"><label>Send the result to</label><select id="whDel">${whDelOpts(tg)}</select><p class="hint">A GitHub comment needs the GitHub connection; Telegram, Discord, Slack and email go to that channel’s home chat.</p><label style="display:flex;align-items:center;justify-content:space-between">Deliver directly (skip the agent) ${toggle(false,'Direct delivery','id="whOnly"')}</label><label>Runs on</label><select id="whAgent">${(S.agentsCache||['default']).map(n=>`<option value="${esc(n)}" ${n===(agentProfile()||'default')?'selected':''}>${esc(ident(n).name)}</option>`).join('')}</select><label>What should aqeelOS do with the event?</label><textarea id="whPrompt" rows="4" placeholder="Review the diff and reply with risks"></textarea>`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="whGo">Create webhook</button>`);
 // delivery choices belong to the agent it runs on
 d.querySelector('#whAgent').onchange=async e=>{const t=(await H('/cron/delivery-targets?profile='+encodeURIComponent(e.target.value)).catch(()=>({targets:[]}))).targets||[];const sel=d.querySelector('#whDel');sel.innerHTML=whDelOpts(t);sel._sync?.()};
 d.querySelector('#whGo').onclick=async e=>{const go=e.currentTarget;if(go.disabled)return;const body={name:$('#whName').value.trim(),description:$('#whDesc').value.trim(),events:$('#whEv').value.split(',').map(s=>s.trim()).filter(Boolean),deliver:$('#whDel').value||undefined,deliver_only:$('#whOnly').checked,prompt:$('#whPrompt').value.trim()};if(!body.name)return toast('Give it a name','err');
  go.disabled=true;   // one webhook per press: a second would be made with a second secret
  try{const r=await post(H,'/webhooks?profile='+encodeURIComponent($('#whAgent')?.value||(agentProfile()||'default')),body);const pubUrl=location.origin+(r.url_path||'/webhooks/'+encodeURIComponent(r.name||body.name));drawer('Webhook created',`<p style="margin:0 0 14px;color:var(--ink-2)">Copy these into the other service. <b>The secret is shown only once.</b></p><label>URL</label><div style="display:flex;gap:8px"><input readonly value="${esc(pubUrl)}"><button data-act="copy-text" data-text="${esc(pubUrl)}">Copy</button></div><label>Secret</label><div style="display:flex;gap:8px"><input readonly value="${esc(r.secret||'')}" style="font-family:var(--mono)"><button data-act="copy-text" data-text="${esc(r.secret||'')}">Copy</button></div>`,`<button class="primary" data-act="close" onclick="render()">Done</button>`)}catch(er){fail(er)}finally{go.disabled=false}}};

/* ===================== Channels › Who can message ===================== */
PAGES.pairing=async(p,el)=>{const gone=pageTok(el);
 const me=(agentProfile()||'default');let links=[];try{links=(await UI('/ui/channels/links?agent='+encodeURIComponent(me))).links||[]}catch{}if(gone())return;
 const lists=await Promise.all([{prof:me,label:''},...links.map(l=>({prof:l.name,label:linkTitle(l)}))].map(async x=>({...x,d:await H('/pairing?profile='+encodeURIComponent(x.prof)).catch(()=>({pending:[],approved:[],err:true}))})));if(gone())return;
 const tag=(u)=>u.__label?' · '+esc(u.__label):'',bad=lists.filter(x=>x.d.err).map(x=>x.label||ident(x.prof).name);
 const d={pending:lists.flatMap(x=>(x.d.pending||[]).map(u=>({...u,__prof:x.prof,__label:x.label}))),approved:lists.flatMap(x=>(x.d.approved||[]).map(u=>({...u,__prof:x.prof,__label:x.label})))};
 const who=u=>`${logoImg(CH_DOMAINS[u.platform],(u.platform||'?')[0].toUpperCase(),CH_COLORS[u.platform])}<div class="txt"><b>${esc(u.user_name||u.user_id)} · ${esc(pretty(u.platform))}${tag(u)}</b><span>${[u.request_id?'Code '+esc(u.request_id):'',u.age_minutes!=null?(u.age_minutes<90?Math.round(u.age_minutes)+' min ago':ago(Date.now()/1000-u.age_minutes*60)):'',u.user_name&&u.user_id?'ID '+esc(u.user_id):''].filter(Boolean).join(' · ')}</span></div>`;
 Pages._pairProfs=[...new Set(d.pending.map(u=>u.__prof))];Pages._pairAdd={profs:lists.map(x=>({prof:x.prof,label:x.label})),all:false};setActions(d.pending.length?`<button class="ghost" data-act="pair-clear">Decline all waiting</button>`:'');
 el.innerHTML=`${bad.length?errLine('requests for '+bad.join(', ')):''}<div class="panel card"><h2 class="h-row">People waiting<span class="chip">${d.pending.length}</span></h2><p class="sub">Someone messaged one of ${esc(ident(me).name)}’s channels and needs your OK before the agent answers them.</p>${(d.pending||[]).map(u=>`<div class="row" style="padding:12px 12px;margin:0 -12px;border:0"><div class="main-c">${who(u)}</div><div class="act"><button class="primary" data-act="pair-ok" data-p="${esc(u.platform)}" data-r="${esc(u.request_id)}" data-prof="${esc(u.__prof)}">Approve</button></div></div>`).join('')||'<p class="hint" style="margin:0">Nobody is waiting.</p>'}</div>
 <div class="panel card"><div class="h-row"><h2 class="h-row" style="margin:0">Approved<span class="chip">${d.approved.length}</span></h2><button data-act="pair-add">${icon('plus',15)}Add a person</button></div><p class="sub">These people can message ${esc(ident(me).name)}.</p>${(d.approved||[]).map(u=>`<div class="row" style="padding:12px 12px;margin:0 -12px;border:0"><div class="main-c">${who(u)}</div><div class="act"><button class="ghost" data-act="pair-revoke" data-p="${esc(u.platform)}" data-u="${esc(u.user_id)}" data-prof="${esc(u.__prof)}">Remove access</button></div></div>`).join('')||'<p class="hint" style="margin:0">No one yet. Approve requests above once your channels are connected, or add a person yourself.</p>'}</div>`;
 pairMarks(el)};
/* Add a person by hand: approve someone on one of the agent's channels before they message it. The server checks the ID
   per app and writes the approval the engine's own way; such people show "Added by hand" with the note. */
const PAIR_HELP={whatsapp:['Phone number','6281234567890','Their WhatsApp number with the country code (62 for Indonesia). Spaces, dashes and a leading + are fine; a number starting with 0 needs its country code instead.','tel'],
 telegram:['Telegram user ID','123456789','Their numeric user ID. A bot cannot look up an @username before that person writes to it, so ask them to message @userinfobot in Telegram: it replies with their ID.','numeric'],
 slack:['Slack member ID','U0123ABCD','In Slack, open their profile, press ⋮ and choose Copy member ID.','text'],
 discord:['Discord user ID','123456789012345678','In Discord: Settings, Advanced, switch on Developer Mode, then right-click the person and choose Copy User ID.','numeric'],
 email:['Email address','name@example.com','The address they write from.','email']};
async function pairAddDrawer({profs=[],all=false}={}){
 const got=await Promise.all(profs.map(x=>H('/messaging/platforms?profile='+encodeURIComponent(x.prof)).then(r=>(r.platforms||r||[]).filter(p=>PAIR_HELP[p.id]&&(p.configured||p.state==='connected')).map(p=>({prof:x.prof,pf:p.id,label:(all?ident(x.prof.split('--')[0]).name+' · ':'')+(x.label||appName(p.id))}))).catch(()=>[])));
 const opts=got.flat();if(!opts.length)return toast('Connect WhatsApp, Telegram, Slack, Discord or email first, then add people to it.','err');
 const d=drawer('Add a person',`<p class="hint" style="margin:0 0 10px">Approve someone before they message, so the agent answers them from their first message.</p>
  <label for="paCh">Channel</label><select id="paCh">${opts.map((o,i)=>`<option value="${i}">${esc(o.label)}</option>`).join('')}</select>
  <label for="paId" id="paIdL"></label><input id="paId" autocomplete="off"><p class="hint" id="paHelp"></p>
  <label for="paName">Name</label><input id="paName" autocomplete="off" maxlength="80" placeholder="Who this is">
  <label for="paNote">Note (optional)</label><input id="paNote" autocomplete="off" maxlength="140" placeholder="For example: our supplier">`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="paGo">Add</button>`);
 const sel=d.querySelector('#paCh'),id=d.querySelector('#paId');
 const paint=()=>{const o=opts[+sel.value],h=PAIR_HELP[o.pf];d.querySelector('#paIdL').textContent=h[0];id.placeholder=h[1];id.inputMode=h[3];id.type=h[3]==='email'?'email':'text';d.querySelector('#paHelp').textContent=h[2]};sel.onchange=paint;paint();
 d.querySelector('#paGo').onclick=async e=>{const b=e.currentTarget;if(b.disabled)return;const o=opts[+sel.value];b.disabled=true;
  try{await post(UI,'/ui/channels/approve-person',{agent:o.prof,platform:o.pf,id:id.value,name:d.querySelector('#paName').value,note:d.querySelector('#paNote').value});closeLayers();toast((d.querySelector('#paName').value.trim()||'They')+' can message '+ident(o.prof.split('--')[0]).name+' now');reload()}catch(er){fail(er)}finally{b.disabled=false}}}
ACT['pair-add']=()=>pairAddDrawer(Pages._pairAdd||{profs:[{prof:agentProfile()||'default',label:''}]});
// people added by hand: marked on their Approved row, with the note, and the mark is forgotten when access is removed
async function pairMarks(el){let all={};try{all=await UI('/ui/channels/approvals-added')}catch{return}const list=Object.entries(all);if(!list.length)return;
 const same=(pf,a,b)=>pf==='whatsapp'?String(a).split('@')[0].split(':')[0].replace(/\D/g,'')===String(b).replace(/\D/g,''):String(a).toLowerCase()===String(b).toLowerCase();
 el.querySelectorAll('[data-act="pair-revoke"]').forEach(btn=>{const {prof,p,u}=btn.dataset;const hit=list.find(([k])=>{const [a,pf,...r]=k.split('|');return a===prof&&pf===p&&same(p,u,r.join('|'))});if(!hit)return;
  const [k,v]=hit;btn.dataset.hand=k.split('|').slice(2).join('|');const t=btn.closest('.row')?.querySelector('.txt');if(!t||t.querySelector('.hand-chip'))return;
  t.querySelector('b')?.insertAdjacentHTML('beforeend',` <span class="chip hand-chip" title="Added by ${esc(v.by||'someone')}${v.t?' '+esc(when(new Date(v.t).toISOString())):''}">Added by hand</span>`);
  if(v.note)t.querySelector('b')?.insertAdjacentHTML('afterend',`<span class="ch-note">${esc(v.note)}</span>`)})}
ACT['pair-ok']=async a=>{try{await post(H,'/pairing/approve?profile='+encodeURIComponent(a.dataset.prof||S.profile||'default'),{platform:a.dataset.p,request_id:a.dataset.r,profile:a.dataset.prof||S.profile||undefined});toast('Approved');reload()}catch(e){fail(e)}};
ACT['pair-revoke']=async a=>{if(!await confirmBox('Remove access?','They can no longer message your agents.','Remove access'))return;try{await post(H,'/pairing/revoke?profile='+encodeURIComponent(a.dataset.prof||S.profile||'default'),{platform:a.dataset.p,user_id:a.dataset.u,profile:a.dataset.prof||S.profile||undefined});
 if(a.dataset.hand)await post(UI,'/ui/channels/approve-person/forget',{agent:a.dataset.prof||S.profile||'default',platform:a.dataset.p,id:a.dataset.hand}).catch(()=>{});toast('Access removed');reload()}catch(e){fail(e)}};
// clears every agent and linked connection whose requests are on screen, not only the selected agent's
ACT['pair-clear']=async()=>{const w=$$('[data-act="pair-ok"]').length;if(!await confirmBox('Decline '+(w?plural(w,'waiting request'):'every waiting request')+'?','They are turned away. Each person can ask again by messaging the agent.','Decline all'))return;try{let n=0;for(const pr of Pages._pairProfs?.length?Pages._pairProfs:[agentProfile()||'default'])n+=(await post(H,'/pairing/clear-pending?profile='+encodeURIComponent(pr))).cleared||0;toast('Cleared '+plural(n,'request'));reload()}catch(e){fail(e)}};

