 tts:['mic','Turns text into spoken audio.'],skills:['puzzle','Finds and follows its skills, and writes new ones.'],memory:['brain','Remembers things about you and its work between chats.'],
 session_search:['search','Looks back through earlier chats.'],todo:['list','Keeps a to-do list while it works through a task.'],clarify:['chat','Asks you a question when something is unclear.'],
 delegation:['fork','Hands parts of a task to helper agents that work side by side.'],cronjob:['clock','Creates and changes schedules.'],
 send_message:['send','Sends messages to your channels, like Telegram or WhatsApp.'],messaging:['send','Sends messages to your channels, like Telegram or WhatsApp.'],
