/* ===================== System › Status ===================== */
PAGES.status=async(p,el)=>{const gone=pageTok(el);
 setActions(`<button data-act="gw-restart">${icon('refresh',16)}Restart agents</button>`);
 const [s,ses]=await Promise.all([H('/status'),H('/sessions'+qp({limit:8,offset:0,order:'recent'}))]);if(gone())return;S.status=s;paintSide();paintBanner();
 const plats=Object.entries(s.gateway_platforms||{});const connected=plats.filter(([,v])=>v.state==='connected');
 // why the agents or a channel stopped, said up front (the engine records the reason)
 const gwDown=/^(startup_failed|stopped|gateway_stopped)$/.test(s.gateway_state||'')||(!s.gateway_running&&s.gateway_exit_reason);
 const alerts=[gwDown?['The agents are not running',s.gateway_exit_reason?'Why they stopped: '+s.gateway_exit_reason:'They stopped without saying why. Restart them, or look at the logs.']:null,...plats.filter(([,v])=>/^(fatal|startup_failed|disconnected)$/.test(v.state)).map(([k,v])=>[pretty(k)+(v.state==='fatal'?' stopped working':v.state==='startup_failed'?" couldn't start":' lost its connection'),v.error_message||'No reason was given.'])].filter(Boolean);
 const upd=v=>{const t=v.updated_at;if(!t)return '';const sec=typeof t==='number'?t:Date.parse(t)/1000;return isNaN(sec)?'':'updated '+ago(sec)};
 el.innerHTML=`${alerts.map(([t,d])=>`<div class="card status-alert" role="alert">${icon('alert',16)}<div><b>${esc(t)}</b><span>${esc(d)}</span></div></div>`).join('')}<div class="stats">${[['Agents',gwState(s).label,esc(gwState(s).say||(s.gateway_pid?'process '+s.gateway_pid:''))],['Active now',String(s.active_sessions??'—'),'in the last 5 minutes'],['Connected',String(connected.length),connected.map(([k])=>pretty(k)).join(', ')||'nothing yet'],['Version',esc(s.version),s.release_date?'released '+esc(s.release_date):'']].map(([a,b,c],i)=>`<div class="card stat" ${st(i)}><span class="th">${a}</span><b>${b}</b><small>${c}</small></div>`).join('')}</div>
 <div class="two"><div class="card list"><div class="list-head"><span class="th">Recent sessions</span><span class="th">Tokens</span></div>${(ses.sessions||[]).map((c,i)=>`<div class="row clickable" ${st(i)} data-go="/chat/${esc(c.id)}"><div class="main-c"><span class="ic">${icon(srcIcon(c.source),16)}</span><div class="txt"><b>${esc(c.title||noThink(c.preview)||c.id)}</b><span>${ago(c.last_active)} · ${esc(modelLabel(c.model))} · ${plural(c.message_count||0,'message')}</span></div></div><div class="act" style="font-variant-numeric:tabular-nums;color:var(--ink-2)">${num((c.input_tokens||0)+(c.output_tokens||0)+(c.cache_read_tokens||0))}</div></div>`).join('')||'<div class="state-box">No sessions yet.</div>'}</div>
 <div class="card list" style="align-self:start"><div class="list-head"><span class="th">Parts</span><span class="th">State</span></div>${plats.map(([k,v])=>`<div class="row"><div class="txt"><b>${esc(pretty(k))}</b><span>${esc([v.listener_base,v.error_message,upd(v)].filter(Boolean).join(' · '))}</span></div><div class="act">${v.state==='connected'?'<span class="chip ok"><i class="dot"></i>Connected</span>':`<span class="chip ${v.needs_attention?'warn':''}">${esc(pretty(v.state))}</span>`}</div></div>`).join('')||`<div class="state-box">${s.gateway_running?'Running. No channels connected yet.':'Agents are not running.'}</div>`}</div></div>`;
 clearTimeout(Pages._statusT);Pages._statusT=setTimeout(()=>{if(route().page?.id==='status'&&!document.hidden)(pageRun(el),PAGES.status(p,el)).catch(()=>{})},5000);
};

/* ===================== System › Usage ===================== */
// several agents' usage added together: per day and per model
function mergeUsage(all){const day=new Map(),mod=new Map(),sk=new Map();const add=(t,s)=>{for(const [k,v] of Object.entries(s))if(typeof v==='number')t[k]=(t[k]||0)+v};let calls=0;
 for(const u of all){for(const d of u.daily||[]){const t=day.get(d.day)||{day:d.day};add(t,d);day.set(d.day,t)}for(const m of u.by_model||[]){const t=mod.get(m.model)||{model:m.model};add(t,m);mod.set(m.model,t)}
  for(const s of u.skills?.top_skills||[]){const t=sk.get(s.skill)||{skill:s.skill,last_used_at:null};const last=Math.max(t.last_used_at||0,s.last_used_at||0)||null;add(t,s);t.last_used_at=last;sk.set(s.skill,t)}calls+=u.totals?.total_api_calls||0}
 return {daily:[...day.values()].sort((a,b)=>a.day<b.day?-1:1),by_model:[...mod.values()].sort((a,b)=>(b.estimated_cost||0)-(a.estimated_cost||0)),skills:{top_skills:[...sk.values()]},totals:{total_api_calls:calls}}}
// tables sorted by clicking a header (again to reverse); the choice stays while the app is open
const TblSort={state:{},draw:{}};
function sortTable(id,cols,rows,row,def,empty){const s=TblSort.state[id]||(TblSort.state[id]={...def});const c=cols.find(x=>x.k===s.k)||cols[0];const val=r=>c.v?c.v(r):r[c.k];
 const list=rows.slice().sort((a,b)=>{const x=val(a),y=val(b);const o=typeof x==='string'||typeof y==='string'?String(x??'').localeCompare(String(y??'')):(x??-1)-(y??-1);return s.dir==='asc'?o:-o});
 return `<table data-tsort="${id}"><thead><tr>${cols.map(x=>x.k?`<th class="th${x.num?' num':''} sortable" data-k="${x.k}" aria-sort="${x.k===s.k?(s.dir==='asc'?'ascending':'descending'):'none'}"><button type="button">${esc(x.l)}<span class="sort-ar${x.k===s.k?' on':''}${x.k===s.k&&s.dir==='asc'?' up':''}" aria-hidden="true">↓</span></button></th>`:`<th class="th${x.num?' num':''}">${esc(x.l)}</th>`).join('')}</tr></thead><tbody>${list.map(row).join('')||`<tr><td colspan="${cols.length}" style="color:var(--muted)">${esc(empty)}</td></tr>`}</tbody></table>`}
function sortClicks(el){el.addEventListener('click',e=>{const b=e.target.closest('th.sortable button');if(!b)return;const t=b.closest('[data-tsort]'),id=t?.dataset.tsort,k=b.parentElement.dataset.k,s=TblSort.state[id];if(!s||!TblSort.draw[id])return;
 if(s.k===k)s.dir=s.dir==='asc'?'desc':'asc';else{s.k=k;s.dir=b.parentElement.classList.contains('num')?'desc':'asc'}t.outerHTML=TblSort.draw[id]();const n=el.querySelector(`[data-tsort="${id}"]`);n?.querySelector('tbody')?.classList.add('resort');n?.querySelector(`th[data-k="${k}"] button`)?.focus()})}
ACT['usage-pick']=async a=>{const list=await viewAgents();const who=S.usageAgent||'*';
 menu(a,[{header:'Whose usage'},{label:'All agents',icon:'layers',sub:'Every agent added together',on:who==='*',run:()=>{S.usageAgent='*';reload()}},'-',...list.map(n=>({label:ident(n).name,icon:'user',ava:agentAvatar(n,20,{title:false}),on:n===who,run:()=>{S.usageAgent=n;reload()}}))],{search:list.length>8,matchWidth:true})};
ACT['currency-pick']=a=>{const c=currency(),admin=S.me?.admin!==false,def=S.defaults?.currency||'USD';
 menu(a,[{header:'Show costs in'},{label:'US dollars',sub:'$',on:c==='USD',run:()=>setCurrency('USD')},{label:'Rupiah',sub:'Rp, at today’s rate',on:c==='IDR',run:()=>setCurrency('IDR')},...(admin&&c!==def?['-',{label:'Use '+(c==='IDR'?'rupiah':'US dollars')+' for everyone',icon:'user',sub:'For people who haven’t picked one',run:()=>ACT['currency-default']()}]:[])],{matchWidth:false})};
ACT['currency-default']=async()=>{try{await post(UI,'/ui/defaults',{currency:currency()});S.defaults={...(S.defaults||{}),currency:currency()};toast('Everyone who hasn’t picked a currency now sees '+(currency()==='IDR'?'rupiah':'US dollars'));reload()}catch(e){fail(e)}};
PAGES.usage=async(p,el)=>{const gone=pageTok(el);
 const days={'7 days':7,'30 days':30,'90 days':90}[S.tab.usage||'7 days'];
 // dollars or rupiah: the tab sets the person's choice, which every cost in the app follows
 const list=await viewAgents().catch(()=>[]);if(gone())return;const who=S.usageAgent&&(S.usageAgent==='*'||list.includes(S.usageAgent))?S.usageAgent:list.length>1?'*':(S.profile||'default');
 const cur=currency()==='IDR'?'Rp IDR':'$ USD',isDefault=currency()===(S.defaults?.currency||'USD');
 setActions('<div class="u-bar">'+(list.length>1?`<button class="u-pick" data-act="usage-pick" aria-haspopup="menu" title="Whose usage to show">${icon(who==='*'?'layers':'user',15)}<span>${who==='*'?'All agents':esc(ident(who).name)}</span>${icon('chevD',14)}</button>`:'')+`<button class="u-pick" data-act="currency-pick" aria-haspopup="menu" title="Currency for costs"><span>${cur}</span>${icon('chevD',14)}</button>`+tabs('usage',['7 days','30 days','90 days'])+`<button class="u-pick icon" data-act="reload" title="Refresh" aria-label="Refresh">${icon('refresh',15)}</button></div>`);placePills();
 const bad=[],one=a=>H('/analytics/usage?days='+days+'&profile='+encodeURIComponent(a)).catch(()=>{bad.push(ident(a).name);return{daily:[],by_model:[]}});
 const u=who==='*'?mergeUsage(await Promise.all((list.length?list:['default']).map(one))):await one(who);if(gone())return;const daily=u.daily||[];
 const sum=k=>daily.reduce((a,d)=>a+(d[k]||0),0);const inp=sum('input_tokens'),out=sum('output_tokens'),cache=sum('cache_read_tokens'),cost=sum('estimated_cost'),actual=sum('actual_cost'),ses=sum('sessions');
 const hit=inp+cache?Math.round(cache/(inp+cache)*100):0;
 const series=Array.from({length:days},(_,i)=>{const d=new Date(Date.now()-(days-1-i)*864e5).toISOString().slice(0,10);const r=daily.find(x=>x.day===d)||{};return {d,i:(r.input_tokens||0)+(r.cache_read_tokens||0),o:r.output_tokens||0,c:r.estimated_cost||0}});
 const max=Math.max(1,...series.map(s=>s.i+s.o)),calls=sum('api_calls')||u.totals?.total_api_calls||0,skills=u.skills?.top_skills||[];
 const bars=`${bad.length?alertBox(`Usage for ${esc(bad.join(', '))} couldn’t be loaded, so these totals are incomplete.`):''}`;
 if(!daily.length&&!skills.length&&!(u.by_model||[]).length){el.innerHTML=bars+emptyBox('No usage in the last '+days+' days','Start a chat and its tokens, costs and skills show up here.',`<button class="primary" data-act="new">${icon('plus',16)}New chat</button>`);return}
 const cost$=x=>money(x||0,{cents:true});
 TblSort.draw.umodel=()=>sortTable('umodel',[{k:'model',l:'Model',v:m=>modelLabel(m.model)},{k:'sessions',l:'Sessions',num:1},{k:'input_tokens',l:'Input',num:1},{k:'output_tokens',l:'Output',num:1},{k:'estimated_cost',l:'Est. cost',num:1}],u.by_model||[],m=>`<tr><td>${esc(modelLabel(m.model))}</td><td class="num">${m.sessions||0}</td><td class="num">${num(m.input_tokens||0)}</td><td class="num">${num(m.output_tokens||0)}</td><td class="num">${cost$(m.estimated_cost)}</td></tr>`,{k:'estimated_cost',dir:'desc'},'No usage yet');
 TblSort.draw.uday=()=>sortTable('uday',[{k:'day',l:'Day'},{k:'sessions',l:'Sessions',num:1},{k:'input_tokens',l:'Input',num:1},{k:'output_tokens',l:'Output',num:1},{k:'estimated_cost',l:'Cost',num:1}],daily,d=>`<tr><td>${esc(d.day)}</td><td class="num">${d.sessions||0}</td><td class="num">${num(d.input_tokens||0)}</td><td class="num">${num(d.output_tokens||0)}</td><td class="num">${cost$(d.estimated_cost)}</td></tr>`,{k:'day',dir:'desc'},'No usage yet');
 TblSort.draw.uskill=()=>sortTable('uskill',[{k:'skill',l:'Skill'},{k:'view_count',l:'Loads',num:1},{k:'manage_count',l:'Edits',num:1},{k:'total_count',l:'Total',num:1},{k:'last_used_at',l:'Last used',num:1}],skills,s=>`<tr><td>${esc(s.skill)}</td><td class="num">${num(s.view_count||0)}</td><td class="num">${num(s.manage_count||0)}</td><td class="num">${num(s.total_count||0)}</td><td class="num">${s.last_used_at?ago(s.last_used_at>1e12?s.last_used_at/1000:s.last_used_at):'—'}</td></tr>`,{k:'total_count',dir:'desc'},'No skills used yet');
 el.innerHTML=`${bars}<div class="stats">${[['Tokens',num(inp+out+cache),`in ${num(inp)} · cached ${num(cache)} · out ${num(out)}`],['Cache hit',hit+'%','of input read from cache'],['Est. cost',money(cost,{cents:true}),actual?'actual $'+actual.toFixed(2):'list price; plans may cost $0'],['Sessions',num(ses),(ses/days).toFixed(1)+' a day'+(calls?' · '+num(calls)+' API calls':'')]].map(([a,b,c],i)=>`<div class="card stat" ${st(i)}><span class="th">${a}</span><b>${b}</b><small>${esc(c)}</small></div>`).join('')}</div>
 <p class="hint u-note">These are estimates from aqeelOS’ own records. Helper-model calls, retries and cache writes aren’t counted, so check your provider’s billing for exact numbers.</p>
 <div class="panel card"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><h2>Tokens per day</h2><div class="legend"><span><i style="background:var(--blue)"></i>Input + cache</span><span><i style="background:var(--sky-1)"></i>Output</span></div></div><div class="chart">${series.map((s,k)=>`<div class="b" title="${s.d}: ${num(s.i)} in · ${num(s.o)} out · ${money(s.c,{cents:true})}"><i class="in" style="height:${s.i/max*100}%;animation-delay:${k*12}ms"></i><i class="out" style="height:${Math.max(s.o?1:0,s.o/max*100)}%;animation-delay:${k*12+40}ms"></i></div>`).join('')}</div><div class="chart-x"><span>${series[0].d.slice(5)}</span><span>${series[Math.floor(days/2)].d.slice(5)}</span><span>${series[days-1].d.slice(5)}</span></div></div>
 <div class="stack-2"><div class="panel card"><h2>By model</h2><div class="tbl">${TblSort.draw.umodel()}</div></div>
 <div class="panel card"><h2>By day</h2><div class="tbl">${TblSort.draw.uday()}</div></div></div>
 <div class="panel card"><h2>Skills used</h2><p class="sub">How often each skill was loaded or edited${who==='*'?', every agent added together':''}.</p><div class="tbl">${TblSort.draw.uskill()}</div></div>`;
 if(!el._sortOn){el._sortOn=1;sortClicks(el)}
};

/* ===================== System › Logs ===================== */
PAGES.logs=async(p,el)=>{
 const o=S.logs||(S.logs={file:'agent',level:'ALL',component:'all',lines:200,live:true});
 setActions(`<button data-act="log-refresh" title="Load the latest lines now">${icon('refresh',16)}Refresh</button><label style="display:flex;align-items:center;gap:10px;font-size:13.5px;color:var(--ink-2)">${toggle(o.live,'Live','data-act="log-live"')}Live</label>`);
 const map={Agent:'agent',Channels:'gateway',Errors:'errors'},FILES={agent:'agent.log',gateway:'gateway.log',errors:'errors.log'};
 el.innerHTML=`<div class="toolbar">${tabs('logfile',['Agent','Channels','Errors'],Object.keys(map).find(k=>map[k]===o.file))}<select id="lgL" style="width:auto">${['ALL','DEBUG','INFO','WARNING','ERROR'].map(x=>`<option ${x===o.level?'selected':''}>${x}</option>`).join('')}</select><select id="lgC" style="width:auto">${['all','gateway','agent','tools','cli','cron'].map(x=>`<option ${x===o.component?'selected':''}>${x}</option>`).join('')}</select><select id="lgN" style="width:auto">${[50,100,200,500].map(x=>`<option ${x===o.lines?'selected':''} value="${x}">Last ${x} lines</option>`).join('')}</select></div><p class="log-sum" id="logSum"></p><div class="log" id="logBox">Loading…</div>`;placePills();
 const box=$('#logBox'),sum=$('#logSum');
 const load=async()=>{sum.textContent=[FILES[o.file]||o.file,o.level==='ALL'?'every level':o.level,o.component==='all'?'every part':'only '+o.component,'last '+o.lines+' lines'].join(' · ');
  try{const d=await H('/logs'+qp({file:o.file,lines:o.lines,level:o.level==='ALL'?'':o.level,component:o.component==='all'?'':o.component}));if(!box.isConnected)return;const atEnd=box.scrollHeight-box.scrollTop-box.clientHeight<40;const ls=d.lines||[];
   box.innerHTML=ls.length?ls.map(l=>logLine(l)).join('\n'):`<span class="d">${o.level!=='ALL'||o.component!=='all'?'Nothing matches these filters yet.':'Nothing written to this log yet.'}</span>`;if(atEnd)box.scrollTop=box.scrollHeight}
  catch(e){if(e?.stale||!box.isConnected)return;box.innerHTML=`<span class="e">Couldn’t load this log: ${esc(e.message)}</span>`}};
 Pages._logLoad=load;await load();box.scrollTop=box.scrollHeight;
 $('#lgL').onchange=e=>{o.level=e.target.value;load()};$('#lgC').onchange=e=>{o.component=e.target.value;load()};$('#lgN').onchange=e=>{o.lines=+e.target.value;load()};
 el.querySelector('[data-tabs=logfile]').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b){o.file=map[b.dataset.tab];load()}});
 clearInterval(Pages._logT);Pages._logT=setInterval(()=>{if(route().page?.id!=='logs')return clearInterval(Pages._logT);if(o.live&&!document.hidden)load()},5000);
};
ACT['log-live']=a=>{S.logs.live=a.checked};
ACT['log-refresh']=()=>Pages._logLoad?.();
// a line's level is the word right after its time stamp, so a message that merely mentions "error" stays plain
const LOG_LEVEL=/^\d{4}-\d{2}-\d{2}[ T][\d:,.]+\s+(DEBUG|INFO|WARNING|WARN|ERROR|CRITICAL|FATAL)\b/;
function logCls(l){const t=LOG_LEVEL.exec(l)?.[1];if(t)return /ERROR|CRITICAL|FATAL/.test(t)?'e':/WARN/.test(t)?'w':t==='DEBUG'?'d':'';const u=l.toUpperCase();return /\b(ERROR|CRITICAL|FATAL)\b/.test(u)||u.startsWith('TRACEBACK (')?'e':/\b(WARNING|WARN)\b/.test(u)?'w':/\bDEBUG\b/.test(u)?'d':''}
const logLine=(l,pre='')=>{const c=logCls(l),e=pre+esc(l.replace(/\n$/,''));return c?`<span class="${c}">${e}</span>`:e};

/* ===================== System › Settings ===================== */
const CFG_WORDS=[['hermes-cli','aqeelos-cli'],['hermes gateway','aqeelos gateway'],['Hermes','aqeelOS']];
const cfgShow=v=>{if(v==null)return v;const t=typeof v==='string'?v:JSON.stringify(v);if(!/hermes/i.test(t))return v;let o=t;for(const [a,b] of CFG_WORDS)o=o.split(a).join(b);try{return typeof v==='string'?o:JSON.parse(o)}catch{return v}};
const cfgSave=v=>{if(typeof v!=='string')return v;let o=v;for(const [a,b] of CFG_WORDS.slice(0,2))o=o.split(b).join(a);return o};
PAGES.settings=async(p,el)=>{const gone=pageTok(el);
 setActions(`<button data-act="cfg-raw">Raw YAML</button><button data-act="cfg-import">${icon('upload',16)}Import</button><button data-act="cfg-export">${icon('download',16)}Export</button><button class="primary" data-act="cfg-save">Save</button>`);
 // searching, switching groups and Load defaults redraw from the unsaved copy instead of fetching it again
 const reuse=Pages._cfgReuse&&Pages._cfg;Pages._cfgReuse=false;
 const [cfg,schema,consent]=await Promise.all([reuse?Pages._cfg:H('/config'),H('/config/schema'),null]);if(gone())return;if(!reuse){Pages._cfgChanged=false;Pages._loadedDefaults=false}Pages._cfg=cfg;Pages._dirty={};
 const get=k=>cfgShow(k.split('.').reduce((o,x)=>o==null?undefined:o[x],cfg));
 const fields=Object.entries(schema.fields||{});const catOf=f=>f.category||'general';const allCats=[...new Set(fields.map(f=>catOf(f[1])))];const order=schema.category_order||[];
 // the engine's order first, then any group it left out, A to Z
 const cats=[...order.filter(c=>allCats.includes(c)),...allCats.filter(c=>!order.includes(c)).sort()];
 const q=(S.cfgQ||'').toLowerCase();const cur=cats.includes(S.cfgCat)?S.cfgCat:cats[0];
 const ctl=(k,f)=>{const v=get(k);const opts=f.options||f.choices||f.enum;
  if(f.type==='boolean'||typeof v==='boolean')return toggle(!!v,k,`data-cfg="${esc(k)}" data-t="bool"`);
  if(opts&&opts.length)return `<select data-cfg="${esc(k)}">${opts.map(o=>`<option ${String(o)===String(v)?'selected':''}>${esc(o)}</option>`).join('')}</select>`;
  if(f.type==='text')return `<textarea data-cfg="${esc(k)}" data-t="str" rows="4">${esc(v??'')}</textarea>`;
  if(cfgNestable(v))return cfgNest(k,v);
  if((f.type==='list'||Array.isArray(v))&&(v==null||Array.isArray(v)&&v.every(x=>x==null||typeof x!=='object'))){const a=v||[];return `<input data-cfg="${esc(k)}" data-t="csv" ${a.length&&a.every(x=>typeof x==='number')?'data-n="1"':''} placeholder="Values, separated by commas" value="${esc(a.join(', '))}">`}
  if(f.type==='list'||Array.isArray(v)||(v&&typeof v==='object'))return `<textarea data-cfg="${esc(k)}" data-t="json" rows="${Array.isArray(v)&&v.length<4?2:4}" style="font-family:var(--mono);font-size:12px">${esc(JSON.stringify(v??(f.type==='list'?[]:{}),null,1))}</textarea>`;
  const n=f.type==='number'||typeof v==='number';return `<input data-cfg="${esc(k)}" data-t="${n?'num':'str'}" ${n?'type="number" step="any" inputmode="decimal"':''} value="${esc(v??'')}">`};
 const hit=([k,f])=>(k+' '+k.split('.').pop().replace(/_/g,' ')+' '+catOf(f)+' '+pretty(catOf(f))+' '+(f.description||'')).toLowerCase().includes(q);
 const shown=q?cats.flatMap(c=>fields.filter(x=>catOf(x[1])===c&&hit(x))):fields.filter(([k,f])=>catOf(f)===cur);
 Pages._cfgShown=shown.map(x=>x[0]);Pages._cfgScope=q?'Search results':pretty(cur);
 // a heading where the search results move to another group, or where a group's keys move to another section
 let lastS='';const rows=shown.map(([k,f])=>{const sec=q?catOf(f):k.includes('.')?k.split('.')[0]:'';const head=sec&&sec!==lastS&&(q||sec!==cur)?`<div class="cfg-sec">${esc(pretty(sec))}</div>`:'';lastS=sec;const c=ctl(k,f);const row=fieldRow(esc(pretty(k.split('.').pop())),`${f.description?esc(f.description):''}<span class="cfg-key">${esc(k)}</span>`,c);return head+(/cfg-nest|<textarea/.test(c)?row.replace('class="field"','class="field wide"'):row)}).join('');
 el.innerHTML=`<div class="toolbar"><div class="search" style="max-width:none">${icon('search',16)}<input id="cfQ" placeholder="Search ${fields.length} settings" value="${esc(S.cfgQ||'')}">${S.cfgQ?`<button class="ghost icon search-x" data-act="cfg-clearq" title="Clear search" aria-label="Clear search">${icon('x',15)}</button>`:''}</div></div><div class="two wide-main"><div class="panel card"><h2>${q?'Search results':esc(pretty(cur))}</h2><p class="sub">${plural(shown.length,'setting')} · changes apply to new chats, or after the agents restart</p>${rows||'<p class="hint">Nothing matches.</p>'}</div>
 <div style="align-self:start;display:grid;gap:16px"><div class="panel card" style="margin:0"><h2>Groups</h2><p class="sub">Jump to a section</p>${cats.map(c=>`<button class="item ${c===cur&&!q?'on':''}" data-act="cfg-cat" data-c="${esc(c)}">${esc(pretty(c))}<span class="n">${fields.filter(f=>catOf(f[1])===c).length}</span></button>`).join('')}</div>
 <div class="panel card" style="margin:0"><h2>Reset</h2><p class="sub">${q?'Put the settings found by this search back to their defaults':'Put the settings in this group back to their defaults'}. Nothing else changes, and you still need to Save.</p><button data-act="cfg-defaults" ${shown.length?'':'disabled'}>${q?'Reset these results':'Reset this group'}</button></div></div></div>`;placePills();
 el.addEventListener('input',e=>{const i=e.target.closest('[data-cfg]');if(i)Pages._dirty[i.dataset.cfg]=i});el.addEventListener('change',e=>{const i=e.target.closest('[data-cfg]');if(i)Pages._dirty[i.dataset.cfg]=i});
 let t;$('#cfQ').oninput=e=>{clearTimeout(t);t=setTimeout(()=>{try{cfgApply()}catch(er){return cfgFail(er)}Pages._cfgReuse=true;S.cfgQ=e.target.value;(pageRun(el),PAGES.settings(p,el)).then(()=>{const i=$('#cfQ');i.focus();i.setSelectionRange(i.value.length,i.value.length)})},250)};
 
};
// folds the edited fields into the unsaved copy of the settings
function cfgApply(){const c=Pages._cfg,dirty=Object.entries(Pages._dirty||{});for(const [k,i] of dirty){const t=i.dataset.t;let v;if(t==='bool')v=i.checked;else if(t==='num'){v=i.value.trim()===''?0:Number(i.value);if(Number.isNaN(v))throw new Error('“'+pretty(k.split('.').pop())+'” needs a number')}else if(t==='csv'){v=i.value.split(',').map(x=>cfgSave(x.trim())).filter(Boolean);if(i.dataset.n&&v.every(x=>!Number.isNaN(Number(x))))v=v.map(Number)}else v=t==='json'?JSON.parse(cfgSave(i.value)||'null'):cfgSave(i.value);const parts=k.split('.');let o=c;parts.slice(0,-1).forEach(x=>o=o[x]??(o[x]={}));o[parts.at(-1)]=v;delete Pages._dirty[k]}if(dirty.length)Pages._cfgChanged=true}
// objects and lists of objects get one labelled box per value (keys with dots in them stay as JSON, their path would be ambiguous)
const cfgDots=v=>v!=null&&typeof v==='object'&&Object.entries(v).some(([s,x])=>s.includes('.')||cfgDots(x));
const cfgNestable=v=>!cfgDots(v)&&(v!=null&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).length>0||Array.isArray(v)&&v.some(x=>x!=null&&typeof x==='object'&&!Array.isArray(x)));
const cfgNest=(p,v)=>{if(Array.isArray(v))return `<div class="cfg-nest">${v.map((x,i)=>`<div class="cfg-leaf"><small>Item ${i+1}</small>${cfgNest(p+'.'+i,x)}</div>`).join('')}</div>`;if(v!=null&&typeof v==='object')return `<div class="cfg-nest">${Object.entries(v).map(([s,x])=>`<div class="cfg-leaf"><small>${esc(pretty(s))}</small>${cfgNest(p+'.'+s,x)}</div>`).join('')||'<small class="hint">Empty</small>'}</div>`;
 if(typeof v==='boolean')return `<div>${toggle(v,p,`data-cfg="${esc(p)}" data-t="bool"`)}</div>`;const n=typeof v==='number';return `<input data-cfg="${esc(p)}" data-t="${n?'num':'str'}" ${n?'type="number" step="any" inputmode="decimal"':''} value="${esc(v??'')}">`};
const cfgFail=e=>fail(e.name==='SyntaxError'?new Error('One of the list or object fields is not valid JSON'):e);
ACT['cfg-cat']=a=>{try{cfgApply()}catch(e){return cfgFail(e)}Pages._cfgReuse=true;S.cfgCat=a.dataset.c;S.cfgQ='';reload()};
ACT['cfg-clearq']=()=>{try{cfgApply()}catch(e){return cfgFail(e)}Pages._cfgReuse=true;S.cfgQ='';reload()};
ACT['cfg-save']=async()=>{const c=Pages._cfg;try{cfgApply();if(!Pages._cfgChanged&&!Pages._loadedDefaults)return toast('Nothing changed');await put(H,'/config',{config:c});Pages._dirty={};Pages._cfgChanged=false;Pages._loadedDefaults=false;toast('Settings saved · new chats use them')}catch(e){cfgFail(e)}};
// on one agent's Settings page the form is the source, unsaved edits included; on All agents it is the agent you chat with
const cfgHere=()=>route().page?.id==='settings'&&!showingAll()&&Pages._cfg;
ACT['cfg-export']=async()=>{try{let c;if(cfgHere()){cfgApply();c=Pages._cfg}else c=await H('/config');downloadBlob(new Blob([JSON.stringify(c,null,2)],{type:'application/json'}),'aqeelos-config.json')}catch(e){cfgFail(e)}};
ACT['cfg-import']=()=>pickFile('.json',async f=>{let c;try{c=JSON.parse(await f.text())}catch{return toast('That file is not valid JSON','err')}if(!c||typeof c!=='object'||Array.isArray(c))return toast('That file does not hold settings','err');
 if(cfgHere()){Pages._cfg=c;Pages._dirty={};Pages._cfgChanged=true;Pages._cfgReuse=true;reload();return toast('Imported · check the values, then press Save to keep them')}
 if(!await confirmBox('Replace '+ident(agentProfile()||'default').name+'’s settings?','Every setting of the agent you chat with is replaced with the file’s values. To check them before saving, open that agent’s Settings and import there.','Replace'))return;try{await put(H,'/config',{config:c});toast('Settings imported');reload()}catch(e){fail(e)}});
ACT['cfg-defaults']=async()=>{const ks=Pages._cfgShown||[];if(!ks.length)return toast('Nothing to reset here');try{cfgApply()}catch(e){return cfgFail(e)}
 if(!await confirmBox('Reset '+plural(ks.length,'setting')+'?',(Pages._cfgScope||'This group')+': '+(ks.length===1?'it goes':'they go')+' back to the default. Every other setting stays as it is, and nothing is saved until you press Save.','Reset'))return;
 try{const dft=await H('/config/defaults');for(const k of ks){const parts=k.split('.');const v=parts.reduce((o,x)=>o==null?undefined:o[x],dft);let o=Pages._cfg;parts.slice(0,-1).forEach(x=>o=o[x]!=null&&typeof o[x]==='object'?o[x]:(o[x]={}));if(v===undefined)delete o[parts.at(-1)];else o[parts.at(-1)]=structuredClone(v)}Pages._cfgChanged=true;Pages._cfgReuse=true;reload();toast(plural(ks.length,'setting')+' reset · press Save to keep the change')}catch(e){fail(e)}};
ACT['cfg-raw']=async()=>{try{const r=await H('/config/raw');const d=drawer('config.yaml',`<p class="hint" style="margin:0 0 8px">${esc(r.path||'')}</p><textarea id="rawY" rows="28" style="font-family:var(--mono);font-size:12px;line-height:1.5">${esc(r.yaml)}</textarea>`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="rawGo">Save YAML</button>`);d.style.width='min(720px,100vw)';d.querySelector('#rawGo').onclick=async()=>{try{await put(H,'/config/raw',{yaml_text:$('#rawY').value});closeLayers();toast('config.yaml saved');reload()}catch(e){fail(e)}}}catch(e){fail(e)}};

/* ===================== System › Host ===================== */
PAGES.host=async(p,el)=>{const gone=pageTok(el);
 const [s,cur,hooks,ck,stat,pool,plan,box]=await Promise.all([H('/system/stats'),H('/curator').catch(()=>null),H('/ops/hooks').catch(()=>({hooks:[]})),H('/ops/checkpoints').catch(()=>null),S.status?Promise.resolve(S.status):H('/status').catch(()=>null),H('/credentials/pool').catch(()=>({providers:[]})),H('/gateway/migrate/plan').catch(()=>null),UI('/ui/box').catch(()=>null)]);if(gone())return;
 const canUpd=stat?.can_update_hermes!==false;
 setActions(canUpd?`<button class="primary" data-act="upd-check">${icon('refresh',16)}Check for updates</button>`:'');
 const bm=box?.memory?.limit?box.memory:null,sm=s.memory||{},pct=x=>x==null?'':' ('+Math.round(x)+'%)';
 const up=s.uptime_seconds||0,dur=`${up>=86400?Math.floor(up/86400)+'d ':''}${up>=3600?Math.floor(up%86400/3600)+'h ':''}${Math.floor(up%3600/60)}m`;
 const shared=gwShared(stat),gwOff=stat&&!stat.gateway_running;
 el.innerHTML=`<div class="stats">${[['CPU',s.cpu_count+' cores',`${s.cpu_percent??'—'}% · load ${(s.load_avg||[]).map(x=>x.toFixed(1)).join(' ')}`],bm?['Memory',bytes(bm.used)+' / '+bytes(bm.limit),`AI box ${bm.pct}% · whole server ${bytes(sm.used)} / ${bytes(sm.total)}${pct(sm.percent??(sm.total?sm.used/sm.total*100:null))}`]:['Memory',bytes(sm.used)+' / '+bytes(sm.total),bytes(sm.available)+' free'+(sm.percent!=null?' · '+Math.round(sm.percent)+'% used':'')],['Disk',bytes(s.disk?.used)+' / '+bytes(s.disk?.total),bytes(s.disk?.free)+' free'+(s.disk?.percent!=null?' · '+Math.round(s.disk.percent)+'% used':'')],['Uptime',dur,esc(s.os+' '+s.os_release)]].map(([a,b,c],i)=>`<div class="card stat" ${st(i)}><span class="th">${a}</span><b style="font-size:22px">${b}</b><small>${c}</small></div>`).join('')}</div>
 ${s.psutil===false?`<p class="hint" style="margin:-4px 0 16px">CPU, memory and disk details need the engine’s psutil add-on (pip install psutil on the AI box), so some numbers above may be missing.</p>`:''}
 ${bm&&box.parts?.length?`<div class="panel card mem-parts"><h2>What uses memory</h2><p class="sub">The AI box has ${bytes(bm.limit)} of its own. Near the limit, the system stops the biggest program (often the browser or a reply in progress).${bm.oom_kills?` It has done that ${bm.oom_kills} time${bm.oom_kills>1?'s':''}.`:''}</p>
  ${box.parts.map(x=>`<div class="mem-row"><span>${esc(x.name)}</span><i style="--w:${Math.max(2,Math.round(x.bytes/bm.limit*100))}%"></i><b>${bytes(x.bytes)}</b></div>`).join('')}</div>`:''}
 <div id="updBox"></div>
 <div class="two"><div>
  <div class="panel card"><h2>Start and stop agents</h2><p class="sub">What runs every agent: chats, channels and schedules.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button data-act="gw-restart">${icon('refresh',16)}Restart</button><button data-act="gw-start">${icon('play',16)}Start</button><button data-act="gw-stop">${icon('pause',16)}Stop</button></div>${stat?`<p class="hint" style="margin-top:12px">${esc(gwStateText(stat))}${gwOff||/^(degraded|startup_failed)$/.test(stat.gateway_state||'')?` <button class="ghost" data-act="log-gw">See channel log</button>`:''}</p>`:''}${shared?`<p class="hint">One engine runs ${esc(shared.map(a=>ident(a).name).join(', '))}: starting, stopping or restarting it affects all of them.</p>`:''}<p class="hint gw-note" id="gwNote"${S._gwNote?'':' hidden'}>${S._gwNote||''}</p>${plan&&!plan.already_multiplexed&&(plan.profiles||[]).length>1&&(plan.eligible||(plan.blockers||[]).length)?`<p class="hint" style="margin-top:12px">${plan.eligible?'aqeelOS suggests running every agent from one engine. <button class="ghost" data-act="gw-migrate">Migrate…</button>':'Every agent could run from one engine, but first:'}</p>${(plan.blockers||[]).map(b=>`<p class="hint" style="color:var(--warn);margin:4px 0 0">• ${esc(b)}</p>`).join('')}`:''}</div>
  <div class="panel card"><h2>Background helpers</h2><p class="sub">Skill curator, checkpoints and shell hooks.</p>
   ${cur?fieldRow('Skill curator',`Tidies skills aqeelOS made itself${cur.interval_hours?' · every '+cur.interval_hours+' h':''}${cur.last_run_at?' · last '+when(cur.last_run_at):' · never run'}${cur.enabled===false?' · <span class="chip">Turned off in settings</span>':cur.paused?' · <span class="chip warn">Paused</span>':''}`,`<div style="display:flex;gap:8px;align-items:center">${toggle(!cur.paused&&cur.enabled!==false,'Curator','data-act="cur-toggle"'+(cur.enabled===false?' disabled title="The curator is turned off in Settings"':''))}<button data-act="cur-run">Run now</button></div>`):''}
   ${ck?fieldRow('Checkpoints',`Rollback store · ${bytes(ck.total_bytes)} in ${plural((ck.sessions||[]).length,'session')}`,`<button data-act="ck-prune" ${(ck.sessions||[]).length?'':'disabled title="Nothing to prune"'}>Prune</button>`):''}
   ${fieldRow('Shell hooks',plural((hooks.hooks||[]).length,'hook')+' · run commands on events',`<button data-act="hooks-open">Manage</button>`)}</div>
  <div class="panel card"><h2>Credential pool</h2><p class="sub">Extra API keys aqeelOS rotates through, per provider.</p>${(pool.providers||[]).map(pv=>`<div class="row" style="padding:10px 12px;margin:0 -12px;border-top:1px solid var(--border)"><div class="txt"><b>${esc(pv.provider||pv.name)}</b><span>${plural((pv.entries||pv.keys||[]).length,'key')}</span></div><div class="act pool-keys">${(pv.entries||pv.keys||[]).map((k,i)=>{const tp=k.token_preview||k.redacted||k.preview||'';return `<span class="pool-key"><b>${esc(k.label||'Key '+((k.index??i)+1))}</b>${tp?`<code>${esc(tp)}</code>`:''}${k.auth_type?`<span class="chip">${esc(pretty(k.auth_type))}</span>`:''}${k.last_status?`<span class="chip ${/ok|success|active/i.test(k.last_status)?'ok':/exhaust|limit|fail|error|invalid/i.test(k.last_status)?'warn':''}">${esc(pretty(k.last_status))}</span>`:''}<button class="ghost icon" data-act="pool-del" data-p="${esc(pv.provider||pv.name)}" data-i="${esc(k.index??i)}" aria-label="Remove this key">${icon('x',13)}</button></span>`}).join('')}</div></div>`).join('')||'<p class="hint" style="margin:0 0 10px">None yet.</p>'}<button data-act="pool-add">${icon('plus',15)}Add key</button></div>
 </div><div>
  <div class="panel card"><h2>Maintenance</h2><p class="sub">Each runs in the background with a live log.</p><div style="display:flex;gap:8px;flex-wrap:wrap">${[['Check for problems','/ops/doctor'],['Security check','/ops/security-audit'],['Back up','/ops/backup'],['Update skills','/skills/hub/update'],['Instruction size','/ops/prompt-size'],['Download support file','/ops/dump'],['Update settings format','/ops/config-migrate']].map(([l,u])=>`<button data-act="op" data-u="${u}" data-l="${esc(l)}">${l}</button>`).join('')}<button data-act="op-restore">Restore…</button><button data-act="debug-share">${icon('link',15)}Share a support report</button></div><div id="bkSlot">${backupRow()}</div></div>
  <div class="panel card"><h2>About this box</h2><p class="sub">${esc(s.hostname)} · ${esc(s.arch)} · ${esc(s.python_impl&&s.python_impl!=='CPython'?s.python_impl+' ':'')}Python ${esc(s.python_version)}${s.python_impl==='CPython'?' (CPython)':''} · aqeelOS engine ${esc(s.hermes_version)}</p></div>
 </div></div>`;
 if(canUpd)updFill(el.querySelector('#updBox'),false);else el.querySelector('#updBox').innerHTML=`<div class="panel card"><h2>Updates</h2><p class="sub" style="margin:0">Updates for this engine are handled outside aqeelOS, by whoever runs the AI box.</p></div>`;
};
// how the engine is doing, in plain words (its own state names are technical)
const GW_STATE={running:'Running: channels are online.',starting:'Starting up.',degraded:'Running, but some channels are offline.',stopped:'Stopped: channels are offline.',startup_failed:'It failed to start.',draining:'Finishing the replies in progress before it stops.'};
const gwStateText=st=>st.gateway_state==='degraded'&&st.gateway_running===false?'A watchdog stopped it because it stopped responding.':(GW_STATE[st.gateway_state]||(st.gateway_running?GW_STATE.running:GW_STATE.stopped))+(st.gateway_heartbeat_stale_s?' It has not checked in for '+Math.max(1,Math.round(st.gateway_heartbeat_stale_s/60))+' min.':'');
const gwShared=st=>{const a=[...new Set((st?.gateway_shared_with||[]).map(String).filter(Boolean))];return a.length>1?a.sort((x,y)=>x==='default'?-1:y==='default'?1:x.localeCompare(y)):null};
ACT['log-gw']=()=>{S.logs={...(S.logs||{level:'ALL',component:'all',lines:200,live:true}),file:'gateway'};go('/system/logs')};
// the latest engine backup stays here with a Download button (the engine keeps the file on the box)
function backupRow(){const b=S.lastBackup||(S.lastBackup=store.get('lastBackup',null));if(!b?.archive)return '';const name=String(b.archive).split(/[\\/]/).filter(Boolean).pop();
 return `<div class="eb-row"><div class="txt"><b>${b.state==='running'?'Backing up…':b.state==='failed'?'The last backup did not finish':'Latest backup'}</b><span>${esc(name)}${b.t?' · '+ago(b.t/1000):''}</span></div>${b.state==='failed'?'':`<button data-act="bk-download" ${b.state==='running'?'disabled':''}>${icon('download',15)}Download</button>`}</div>`}
const paintBackup=()=>{const el=$('#bkSlot');if(el)el.innerHTML=backupRow()};
async function backupRun(){try{const r=await post(H,'/ops/backup',{});if(r?.ok===false)throw new Error(r.error||r.message||'Failed');
 const b={archive:r.archive||'',state:r.name?'running':'ready',t:Date.now()};S.lastBackup=b;store.set('lastBackup',b);paintBackup();if(!r.name)return toast('Backup saved');
 const st=await actionDrawer('Backing up',r.name);b.state=st&&(st.exit_code===0||st.exit_code==null)?'ready':'failed';store.set('lastBackup',b);paintBackup();if(b.state==='ready'&&b.archive)toast('Backup ready to download')}catch(e){fail(e)}}
ACT['bk-download']=async()=>{const b=S.lastBackup;if(!b?.archive)return;try{const r=await H('/ops/backup/download?archive='+encodeURIComponent(b.archive),{raw:true});if(!r.ok){let m='';try{const j=await r.json();m=j.detail||j.error||''}catch{}throw new Error(r.status===404?'That backup is no longer on the AI box. Make a new one.':m||'The download failed ('+r.status+')')}downloadBlob(await r.blob(),String(b.archive).split(/[\\/]/).filter(Boolean).pop()||'backup.zip')}catch(e){fail(e)}};
async function updFill(b,force){if(!b)return;if(force)b.innerHTML='<div class="skel" style="height:64px;margin-bottom:16px"></div>';try{const r=await H('/hermes/update/check'+(force?'?force=true':''));if(!b.isConnected)return;
 const sub=[r.message,r.current_version,r.rollback_to?'newer than v'+r.rollback_to:r.behind>0?plural(r.behind,'commit')+' behind':''].filter(Boolean).map(esc).join(' · ');
 b.innerHTML=`<div class="panel card upd-card" style="display:flex;align-items:center;gap:16px;justify-content:space-between;flex-wrap:wrap"><div><h2>${r.update_available?'Update available':r.behind==null?'Couldn’t check for updates':'Up to date'}</h2><p class="sub" style="margin:0">${conText(sub)}</p></div>${r.update_available?(r.can_apply?`<button class="primary" data-act="upd-go" data-n="${esc(r.behind)}">Update now</button>`:`<p class="hint" style="margin:0">Run on the AI box: <code>${esc(r.update_command)}</code></p>`):''}</div>`}catch(e){if(force)showError(b,e);else b.innerHTML=''}}
ACT['upd-check']=async()=>{if(S.status?.can_update_hermes===false)return toast('Updates for this engine are handled outside aqeelOS.');const b=$('#updBox');await updFill(b,true);b?.scrollIntoView({block:'nearest',behavior:'smooth'})};
ACT['upd-go']=async a=>{if(!await confirmBox('Update the aqeelOS engine?',`Pulls ${plural(+a.dataset.n||0,'commit')} and restarts aqeelOS. Chats in progress may be interrupted.`,'Update',false))return;runAction('Updating aqeelOS','/hermes/update')};
ACT['gw-start']=()=>restartGateway();   // the proper start (its own session, full environment), not the dashboard's
// stops the engine that runs the agent you chat with: when one engine runs several agents, all of them stop
ACT['gw-stop']=async a=>{const ag=a?.dataset.all?'default':agentProfile()||'default',sh=gwShared(S.status),all=!!sh||ag==='default';
 if(!await confirmBox(all?'Stop the agents?':'Stop '+ident(ag).name+'?',all?'Channels, schedules and chats stop working for '+(sh?sh.map(a=>ident(a).name).join(', '):'every agent')+' until you start them again.':'Its channels, schedules and chats stop until you start it again.','Stop'))return;
 const note=t=>{S._gwNote=t;const n=$('#gwNote');if(n){n.innerHTML=t;n.hidden=!t}};note('');if(a?.isConnected){Press.btn=a;Press.at=Date.now()}
 try{const r=await post(H,'/gateway/stop?profile='+encodeURIComponent(sh?'default':ag));if(r?.ok===false)throw new Error(r.error||r.message||'Failed');if(r?.name)actionDrawer('Stopping the agents',r.name);else toast('Stopped');setTimeout(()=>refreshStatus(),3000)}
 catch(e){if(e.status===409)note(esc(conText(e.message))+' <button class="link-btn" data-act="gw-stop" data-all="1">Stop every agent</button>');else fail(e)}};
ACT['gw-migrate']=async()=>{if(!await confirmBox('Run every agent from one engine?','All agents will run from one engine.','Migrate',false))return;runAction('Moving agents','/gateway/migrate')};
ACT['cur-toggle']=async a=>{try{await put(H,'/curator/paused',{paused:!a.checked});toast(a.checked?'Curator on':'Curator paused')}catch(e){a.checked=!a.checked;fail(e)}};
ACT['cur-run']=()=>runAction('Skill curator','/curator/run');
ACT['ck-prune']=async()=>{if(!await confirmBox('Prune checkpoints?','Deletes the rollback store. Earlier points you could roll a chat’s file changes back to are lost.','Prune'))return;runAction('Pruning checkpoints','/ops/checkpoints/prune')};
ACT['op']=a=>a.dataset.u==='/ops/backup'?backupRun():runAction(a.dataset.l,a.dataset.u);

// Restore: a backup file from this computer, or one already on the AI box. The engine's restore can't ask
// "are you sure?" itself, so it is asked here and the engine is told to go ahead (force).
ACT['op-restore']=()=>{const d=drawer('Restore from a backup',`<div class="approval" style="margin-top:0"><h4>${icon('alert',16)}This replaces what is on the AI box</h4><p>Settings, skills, chats and memory are replaced by the backup’s. This cannot be undone.</p></div><label>A backup file on this computer</label><div><button id="rsFile">${icon('upload',15)}Choose a file…</button></div><label style="margin-top:18px">Or a backup already on the AI box</label><input id="rsPath" placeholder="/full/path/on/the/box/backup.zip" style="font-family:var(--mono)"><p class="hint">The file’s full path on the box, for example one made with Back up.</p>`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="rsGo" style="background:var(--bad);box-shadow:none">Restore from the path</button>`);
 const sure=n=>confirmBox('Restore from '+n+'?','Everything on the AI box is replaced by this backup. This cannot be undone.','Restore');
 const lb=S.lastBackup?.archive;if(lb)d.querySelector('#rsPath').value=lb;
 d.querySelector('#rsFile').onclick=()=>pickFile('.zip,.tar,.gz,.tgz',async f=>{if(!await sure(f.name))return;Press.btn=d.querySelector('#rsFile');Press.at=Date.now();const fd=new FormData();fd.append('force','true');fd.append('file',f,f.name);try{const r=await H('/ops/import-upload',{method:'POST',body:fd});closeLayers();if(r?.name)actionDrawer('Restoring',r.name);else toast('Restore started')}catch(e){fail(e)}});
 d.querySelector('#rsGo').onclick=async()=>{const p=d.querySelector('#rsPath').value.trim();if(!p)return toast('Enter the backup’s path on the AI box','err');if(!await sure(p.split(/[\\/]/).pop()))return;Press.btn=d.querySelector('#rsGo');Press.at=Date.now();try{const r=await post(H,'/ops/import',{archive:p,force:true});closeLayers();if(r?.name)actionDrawer('Restoring',r.name);else toast('Restore started')}catch(e){fail(e)}}};
ACT['pool-add']=async()=>{const d=drawer('Add pooled key',`<label>Provider</label><input id="plP" placeholder="openrouter"><label>API key</label><input id="plK" type="password"><label>Label (optional)</label><input id="plL" placeholder="work account">`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="plGo">Add</button>`);d.querySelector('#plGo').onclick=async()=>{try{await post(H,'/credentials/pool',{provider:$('#plP').value.trim(),api_key:$('#plK').value.trim(),label:$('#plL').value.trim()||undefined});closeLayers();toast('Key added');reload()}catch(e){fail(e)}}};
ACT['pool-del']=async a=>{if(!await confirmBox('Remove this key?','It is taken out of the rotation.','Remove'))return;Press.btn=a;Press.at=Date.now();try{await del(H,'/credentials/pool/'+encodeURIComponent(a.dataset.p)+'/'+a.dataset.i);toast('Removed');reload()}catch(e){fail(e)}};
ACT['hooks-open']=async()=>{const h=await H('/ops/hooks');const d=drawer('Shell hooks',`<div class="approval" style="margin-top:0"><h4>${icon('alert',16)}Hooks run commands on the box</h4><p>Only add commands you trust. A hook does nothing until you grant consent.</p></div>${(h.hooks||[]).map(x=>`<div class="row" style="padding:10px 12px;margin:0 -12px;border-top:1px solid var(--border)"><div class="txt"><b style="font-family:var(--mono);font-size:13px">${esc(x.event)}</b><span style="white-space:normal;font-family:var(--mono)">${esc(x.command)}</span>${x.matcher||(x.allowed??x.approved)===false||x.executable===false?`<span class="hook-meta">${x.matcher?`<span>Only for ${esc(x.matcher)}</span>`:''}${(x.allowed??x.approved)===false?'<span class="chip warn">Not approved yet</span>':''}${x.executable===false?'<span class="chip bad">Can’t run: not executable</span>':''}</span>`:''}</div><div class="act"><button class="ghost icon" data-act="hook-del" data-e="${esc(x.event)}" data-c="${esc(x.command)}" aria-label="Remove">${icon('trash',16)}</button></div></div>`).join('')||'<p class="hint">No hooks yet.</p>'}<h3 style="font-size:15px;margin:22px 0 4px">New hook</h3><label>Event</label><select id="hkE">${(h.valid_events||[]).map(e=>`<option>${esc(e)}</option>`).join('')}</select><label>Command</label><input id="hkC" style="font-family:var(--mono)" placeholder="/home/claude/hooks/notify.sh"><label>Matcher (optional)</label><input id="hkM" placeholder="terminal"><label>Timeout (seconds)</label><input id="hkT" type="number" value="30"><label style="display:flex;align-items:center;justify-content:space-between">I trust this command (grant consent) ${toggle(false,'Consent','id="hkA"')}</label>`,`<button class="ghost" data-act="close">Close</button><button class="primary" id="hkGo">Add hook</button>`);d.querySelector('#hkGo').onclick=async()=>{if(!$('#hkC').value.trim()){$('#hkC').focus();return toast('Enter the command the hook runs','err')}try{await post(H,'/ops/hooks',{event:$('#hkE').value,command:$('#hkC').value.trim(),matcher:$('#hkM').value.trim()||undefined,timeout:+$('#hkT').value||undefined,approve:$('#hkA').checked});toast('Hook added. Restarting the agents so it takes effect…');post(UI,'/ui/gateway/restart').catch(()=>{});ACT['hooks-open']()}catch(e){fail(e)}}};
ACT['hook-del']=async a=>{if(!await confirmBox('Remove this hook?','It stops running and its consent is taken back.','Remove'))return;Press.btn=a;Press.at=Date.now();try{await del(H,'/ops/hooks',{event:a.dataset.e,command:a.dataset.c});toast('Hook removed. Restarting the agents…');post(UI,'/ui/gateway/restart').catch(()=>{});ACT['hooks-open']()}catch(e){fail(e)}};

/* ===================== Agent identity (name, title, picture, description, personality) ===================== */
ACT['ident-open']=(a,e)=>{if(e.target.closest('[data-menu]'))return;editAgent(a.dataset.name)};
// The first sentence of SOUL.md is the agent's self-introduction; we rewrite only that.
const soulIntro=(name,title)=>`You are ${name}${title?', '+title:''}, the AI agent inside aqeelOS. Always call yourself ${name}. Never claim to be another assistant or say another company made you; if someone asks what model powers you, name the model you are running on.`;
function withIntro(soul,name,title){const s=String(soul||'');const intro=soulIntro(name,title);
 if(/^You are [^\n]*?(Nous Research|aqeelOS)[^\n]*?\./.test(s))return s.replace(/^You are [^\n]*?(?:built by Nous Research\.|Claude\.|aqeelOS\.)(?: Always call yourself[^.]*\.)?(?: Never (?:say|claim)[^.]*\.)?(?:[^.]*(?:run on Claude|running on)\.)?/,intro);
 return intro+(s?' '+s:'')}

ACT['key-add']=()=>{const d=drawer('Add a key',`<label>Name</label><input id="kaN" placeholder="ADSPOWER_API_KEY" style="font-family:var(--mono)" autocomplete="off"><p class="hint">Capital letters, digits and underscores, e.g. ADSPOWER_API_KEY.</p><label>Value</label><input id="kaV" type="password" autocomplete="off"><p class="hint">Stored in this agent’s .env file on the AI box only and never shown in full again.</p><p class="err-line" id="kaDup" hidden></p>`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="kaGo">Save key</button>`);
 // the names already set, so adding one twice asks before it overwrites
 let have={};H('/env').then(e=>{have=e||{};Object.keys(have).forEach(k=>Lang.keep(k))}).catch(()=>{});const nm=()=>Lang.keep($('#kaN').value.trim().toUpperCase());
 d.querySelector('#kaN').oninput=()=>{const k=nm(),b=$('#kaDup');b.hidden=!have[k]?.is_set;if(!b.hidden)b.textContent=k+' is already set. Saving replaces its value.'};
 d.querySelectorAll('#kaN,#kaV').forEach(i=>i.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();e.target.id==='kaN'&&!$('#kaV').value?$('#kaV').focus():$('#kaGo').click()}});
 d.querySelector('#kaGo').onclick=async()=>{const k=nm(),v=$('#kaV').value.trim();if(!/^[A-Z_][A-Z0-9_]*$/.test(k))return toast('Use capital letters, digits and underscores, not starting with a digit','err');if(!v)return toast('Paste the value','err');if(have[k]?.is_set&&!await confirmBox('Replace '+k+'?','It already has a value. Saving puts the new one in its place.','Replace'))return;try{await put(H,'/env',{key:k,value:v});closeLayers();toast(k+' saved');reload()}catch(e){fail(e)}}};

/* ===================== Models › Accounts (helpers; the page is in accounts-page.js) ===================== */
const UI=(path,o)=>call('',path,o);
const pctBar=(label,w)=>{if(!w)return '';const c=w.used>=90?'bad':w.used>=70?'warn':'ok';return `<div class="ubar"><div class="ubar-top"><span>${esc(label)}</span><b>${w.used}% used</b></div><div class="ubar-track"><i class="${c}" style="width:${Math.min(100,w.used)}%"></i></div><small>${w.resets?'Resets '+when(w.resets):''}</small></div>`};
// PAGES.accounts lives in accounts-page.js
// Refresh also asks every provider for its model list again, so new models show without waiting
ACT['acct-refresh']=async()=>{Pages._acctFresh=true;try{await G('/api/model/options?refresh=1')}catch{}await Chat.loadModels().catch(()=>{});reload()};
// the ⋯ menu on every account card is in accounts-page.js (Pages.acctMenu)
/* ---------- Reconnect: any account card, the banner on Models and the Bottlenecks item open the Connect dialog for the
   account that is there (connect.js), so nothing new is made and its name, priority and agents stay ---------- */
Pages.reconnect=(key,name)=>Connect.reconnect(key,name||'this account');
ACT['acct-reconnect']=a=>Pages.reconnect(a.dataset.key,a.dataset.name||'this account');
